package cn.studyroom;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.Timestamp;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;

/** One synchronous review transaction composes the existing violation, restriction and booking cores. */
@Service
public class AppealReviewService {
    private final NotificationService messages;
    private final Store db;private final AuthService auth;private final AppealService appeals;private final AppealReviewProjection reviews;private final ViolationService violations;private final RestrictionPolicy restrictions;private final BookingService bookings;private final AuditService audit;private final ObjectMapper json;private final Clock clock;
    public AppealReviewService(Store db,AuthService auth,AppealService appeals,AppealReviewProjection reviews,ViolationService violations,RestrictionPolicy restrictions,BookingService bookings,AuditService audit,ObjectMapper json,Clock clock,NotificationService messages) {this.messages=messages;this.db=db;this.auth=auth;this.appeals=appeals;this.reviews=reviews;this.violations=violations;this.restrictions=restrictions;this.bookings=bookings;this.audit=audit;this.json=json;this.clock=clock;}
    private record Projection(Map<String,Object> appeal,Map<String,Object> violation,Map<String,Object> intent,Map<String,Object> change,List<Map<String,Object>> recalculations,List<Map<String,Object>> others,String hash){}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public Map<String,Object> preview(long actor,long appeal,Requests.AppealReview request){admin(actor);var now=now();var projected=project(actor,appeal,normalize(request),now);var result=envelope(now);result.put("appeal_id",appeal);result.put("appeal_version",projected.appeal().get("version"));result.put("normalized_intent",projected.intent());result.put("impact_hash",projected.hash());result.put("violation_change",projected.change());result.put("automatic_recalculations",projected.recalculations());result.put("other_active_restrictions",projected.others());result.put("post_approval_recheck_required","approved".equals(projected.intent().get("decision")));return result;}
    @Transactional
    public Map<String,Object> confirm(long actor,long appeal,Requests.AppealReviewConfirm request){
        db.lockBookings();admin(actor);Api.require(request!=null,400,"审核确认参数必填");String operation=AttachmentService.uuid(request.operationId(),"operation_id");var previous=db.list("SELECT * FROM appeal_reviews WHERE operation_id=CAST(? AS UUID)",operation);Map<String,Object> normalized;
        try{normalized=normalize(new Requests.AppealReview(request.version(),request.decision(),request.reason(),request.verificationNote(),request.factsConfirmed()));Api.require(request.impactHash()!=null&&request.impactHash().matches("[0-9a-f]{64}"),400,"审核预览指纹格式错误");}catch(Api.Failure failure){if(!previous.isEmpty())throw Api.fail(409,"操作标识已用于其他审核内容，请保留原请求重试");throw failure;}
        String requestHash=hash(Map.of("actor_id",actor,"appeal_id",appeal,"intent",normalized,"impact_hash",request.impactHash()));var now=now();
        if(!previous.isEmpty()){var row=previous.get(0);Api.require(Store.id(row,"actor_id")==actor&&Store.id(row,"appeal_id")==appeal&&requestHash.equals(row.get("request_hash")),409,"操作标识已用于其他审核内容，请保留原请求重试");return receipt(actor,appeal,Store.id(row,"id"),operation,true,now);}
        var current=db.one("SELECT * FROM appeals WHERE id=?",appeal);if(!"submitted".equals(current.get("status"))||Store.id(current,"version")!=((Number)normalized.get("version")).longValue())throw stale();var projected=project(actor,appeal,normalized,now);if(!projected.hash().equals(request.impactHash()))throw stale();
        long review=db.count("SELECT nextval('appeal_reviews_id_seq')"),user=Store.id(current,"user_id"),violation=Store.id(current,"violation_id");String decision=normalized.get("decision").toString(),reason=normalized.get("reason").toString(),note=normalized.get("verification_note").toString(),action="unchanged";Map<String,Object> bookingEffects=null;
        if(decision.equals("approved")){action=violations.revokeForAppeal(actor,violation,review,reason,now);if(!action.equals(projected.change().get("action")))throw new IllegalStateException("违规状态与审核预览矛盾，请核查数据");restrictions.applyAppealRecalculations(actor,review,user,violation,projected.recalculations(),reason,note,now);bookingEffects=bookings.enforceRestrictions(user,now,actor,null);}
        db.update("INSERT INTO appeal_reviews(id,appeal_id,user_id,violation_id,actor_id,decision,reason,verification_note,facts_confirmed,reviewed_at,appeal_version_before,violation_status_before,violation_action,operation_id,request_hash,impact_hash,booking_effects) VALUES(?,?,?,?,?,?,?,?,true,?,?,?,?,CAST(? AS UUID),?,?,CAST(? AS JSONB))",review,appeal,user,violation,actor,decision,reason,note,Timestamp.valueOf(now),current.get("version"),projected.violation().get("status"),action,operation,requestHash,request.impactHash(),bookingEffects==null?null:write(bookingEffects));
        int changed=db.update("UPDATE appeals SET status=?,version=version+1 WHERE id=? AND status='submitted' AND version=?",decision,appeal,current.get("version"));if(changed!=1)throw new IllegalStateException("申诉版本已变化，审核未完成");var qualification=restrictions.eligibility(user,now);String resultText=decision.equals("approved")?"申诉审核通过，原违规已撤销或此前已撤销。":"申诉审核未通过，原违规和独立限制保持。";String qualificationText=Boolean.TRUE.equals(qualification.get("can_book"))?"当前资格允许新预约，仍需按正常规则提交并校验时段。":"当前仍不能新预约，请查看本人当前资格及每条有效限制。";
        long notification=messages.appeal(user,appeal,"申诉审核结果",resultText+"\n公开审核理由：\n"+reason+"\n"+qualificationText+"\n已终止预约与使用记录不会自动恢复。",now);audit.record(actor,"appeal.review","appeal",Long.toString(appeal),reason,Map.of("status",current.get("status"),"version",current.get("version")),Map.of("review_id",review,"decision",decision,"violation_action",action,"notification_id",notification,"verification_source","admin_self_report","facts_confirmed",true));return receipt(actor,appeal,review,operation,false,now);
    }
    private Projection project(long actor,long appeal,Map<String,Object> intent,LocalDateTime now){
        var target=db.one("SELECT * FROM appeals WHERE id=?",appeal);Api.require("submitted".equals(target.get("status")),409,"该申诉已审核，请读取原审核结果");Api.require(Store.id(target,"version")==((Number)intent.get("version")).longValue(),409,"申诉版本已更新，请刷新后重新预览");long user=Store.id(target,"user_id"),violation=Store.id(target,"violation_id");var original=db.one("SELECT * FROM violations WHERE id=? AND user_id=?",violation,user);boolean approved="approved".equals(intent.get("decision"));String before=Store.text(original,"status"),action=approved?(before.equals("active")?"revoked":"already_revoked"):"unchanged";var change=new LinkedHashMap<String,Object>();change.put("id",violation);change.put("status_before",before);change.put("status_after",approved?"revoked":before);change.put("action",action);var recalculations=approved?restrictions.projectAppealRecalculations(user,violation,now):List.<Map<String,Object>>of();var releasing=new HashSet<Long>();for(var row:recalculations)if("released".equals(row.get("outcome")))releasing.add(Store.id(row,"restriction_id"));var other=restrictions.activeRaw(user,now).stream().filter(row->!releasing.contains(Store.id(row,"id"))).map(row->restrictions.detail(Store.id(row,"id"),now,false)).toList();
        var fingerprint=new TreeMap<String,Object>();fingerprint.put("actor_id",actor);fingerprint.put("appeal",Map.of("id",appeal,"version",target.get("version"),"status",target.get("status"),"user_id",user,"violation_id",violation));fingerprint.put("intent",intent);fingerprint.put("violation",original);fingerprint.put("user",db.one("SELECT id,role,status FROM users WHERE id=?",user));
        var batches=db.list("SELECT * FROM restrictions WHERE user_id=? ORDER BY id",user);for(var row:batches)row.put("current_classification",restrictions.status(row,now));fingerprint.put("restrictions",batches);fingerprint.put("original_sources",db.list("SELECT s.*,(SELECT status FROM violations v WHERE v.id=s.violation_id) AS current_status FROM restriction_evaluation_sources s WHERE s.user_id=? ORDER BY s.restriction_id,s.source_order",user));fingerprint.put("original_evaluations",db.list("SELECT * FROM restriction_evaluations WHERE user_id=? ORDER BY restriction_id",user));
        var candidates=db.list("SELECT v.id,v.status,v.occurred_at FROM violations v WHERE v.user_id=? AND NOT EXISTS(SELECT 1 FROM restriction_evaluation_sources s WHERE s.violation_id=v.id) ORDER BY v.occurred_at,v.id",user);for(var row:candidates){var occurred=LocalDateTime.parse(Store.text(row,"occurred_at"));row.put("current_classification",!"active".equals(row.get("status"))?"revoked":occurred.isAfter(now)?"future":occurred.isBefore(now.minusHours(720))?"outside_window":"eligible");}fingerprint.put("unconsumed",candidates);
        var active=db.list("SELECT r.id,r.user_id,r.seat_id,r.res_date,r.start_time,r.end_time,r.status,u.id AS usage_id,u.checkin_at,u.ended_at FROM reservations r LEFT JOIN usage_records u ON u.reservation_id=r.id WHERE r.user_id=? AND r.status IN('pending','checked_in') ORDER BY r.id",user);for(var row:active){Map<String,Object> usage=null;if(row.get("usage_id")!=null){usage=new LinkedHashMap<>();usage.put("checkin_at",row.get("checkin_at"));usage.put("ended_at",row.get("ended_at"));}UsageService.requireReservationState(Store.text(row,"status"),usage,now);row.put("expired_pending",ReservationDeadline.expiredPending(row,now));row.put("scheduled_end_reached",!now.isBefore(Slot.endpoint(LocalDate.parse(Store.text(row,"res_date")),Store.text(row,"end_time")))) ;}fingerprint.put("active_reservations",active);return new Projection(target,original,intent,change,recalculations,other,hash(fingerprint));
    }
    private Map<String,Object> normalize(Requests.AppealReview request){Api.require(request!=null,400,"审核内容必填");Api.require(request.version()!=null&&request.version()>0,400,"申诉版本须为正整数");Api.require(request.decision()!=null&&Set.of("approved","rejected").contains(request.decision()),400,"审核决定须为approved或rejected");String reason=text(request.reason(),1000,"公开审核理由"),note=text(request.verificationNote(),2000,"私有核实依据");Api.require(Boolean.TRUE.equals(request.factsConfirmed()),400,"必须由管理员明确自报已核实事实和依据");var result=new LinkedHashMap<String,Object>();result.put("version",request.version());result.put("decision",request.decision());result.put("reason",reason);result.put("verification_note",note);result.put("facts_confirmed",true);return result;}
    private Map<String,Object> receipt(long actor,long appeal,long review,String operation,boolean replayed,LocalDateTime now){var row=db.one("SELECT user_id FROM appeal_reviews WHERE id=?",review);var result=envelope(now);result.put("operation_id",operation);result.put("replayed",replayed);result.put("appeal",appeals.detailAdminAt(actor,appeal,now));result.put("review",reviews.review(appeal,true));result.put("effects",reviews.effects(review));result.put("eligibility",restrictions.eligibility(Store.id(row,"user_id"),now));return result;}
    private Api.Failure stale(){return Api.fail(409,"申诉、来源或资格影响已变化，请重新预览确认",Map.of("code","appeal_review_preview_stale"));}
    private void admin(long actor){var profile=auth.profile(actor);Api.require("admin".equals(profile.get("role"))&&"active".equals(profile.get("status")),403,"需要启用的管理员权限");}
    private String text(String raw,int limit,String label){String value=raw==null?null:raw.trim();Api.require(value!=null&&!value.isEmpty()&&value.length()<=limit,400,label+"须为1至"+limit+"字");return value;}
    private LocalDateTime now(){return LocalDateTime.ofInstant(clock.instant(),BookingPolicy.CAMPUS_ZONE).truncatedTo(ChronoUnit.MICROS);}
    private Map<String,Object> envelope(LocalDateTime now){var result=new LinkedHashMap<String,Object>();result.put("server_now",AttachmentService.offset(now));result.put("campus_zone",BookingPolicy.CAMPUS_ZONE.getId());return result;}
    private String write(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException("审核事实无法序列化",e);}}
    private Object canonical(Object value){if(value instanceof Map<?,?> map){var sorted=new TreeMap<String,Object>();for(var entry:map.entrySet())sorted.put(entry.getKey().toString(),canonical(entry.getValue()));return sorted;}if(value instanceof List<?> list)return list.stream().map(this::canonical).toList();return value;}
    private String hash(Object value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(write(canonical(json.convertValue(value,Object.class))).getBytes(StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
